// §14.5 Ingesta de documentos: trae un archivo por URL y lo sube al asistente.
//
// El flujo solo transporta (§14): la extraccion de texto, el chunking, los
// embeddings, el hash que evita reindexar lo mismo y el borrado de los chunks
// de la version anterior pasan TODOS dentro de Spring. Aqui no hay ni una
// decision sobre el documento.
//
// Cuerpo esperado:
//   {
//     "url": "https://.../reglamento.pdf",
//     "titulo": "Reglamento de convivencia",
//     "tipo": "REGLAMENTO",          // REGLAMENTO | PROTOCOLO | CIRCULAR | FAQ
//     "audiencias": "TODOS",         // TODOS, o lista: "VIGILANTE,ADMINISTRADOR"
//     "version": "2"
//   }

const esperado = $env.PORTERIA_SECRET;
const TIPOS = ['REGLAMENTO', 'PROTOCOLO', 'CIRCULAR', 'FAQ'];
const AUDIENCIAS = ['TODOS', 'RESIDENTE', 'VIGILANTE', 'ADMINISTRADOR'];
const salida = [];

for (const item of $input.all()) {
  const cabeceras = item.json.headers || {};
  const p = item.json.body || item.json;

  // Este webhook termina llamando a un endpoint de administrador CON el PIN.
  // Sin validar el secreto seria una puerta abierta para indexar cualquier
  // cosa en el reglamento del conjunto (§16).
  if (esperado) {
    const recibido = cabeceras['x-porteria-secret'] || cabeceras['X-Porteria-Secret'];
    if (recibido !== esperado) {
      throw new Error('X-Porteria-Secret invalido: ingesta descartada');
    }
  }

  if (!p.url || !p.titulo) {
    throw new Error('Faltan url o titulo en el cuerpo de la peticion');
  }

  const tipo = String(p.tipo || 'REGLAMENTO').toUpperCase();
  if (!TIPOS.includes(tipo)) {
    throw new Error('Tipo no valido: ' + tipo + '. Validos: ' + TIPOS.join(', '));
  }

  const audiencias = String(p.audiencias || 'TODOS').toUpperCase();
  for (const a of audiencias.split(',').map((s) => s.trim())) {
    if (!AUDIENCIAS.includes(a)) {
      throw new Error('Audiencia no valida: ' + a + '. Validas: ' + AUDIENCIAS.join(', '));
    }
  }

  salida.push({
    json: {
      url: p.url,
      titulo: p.titulo,
      tipo,
      audiencias,
      version: String(p.version || '1'),
    },
  });
}

return salida;
